def two_sum(nums, target):
    mp = {}
    for i, num in enumerate(nums):
        if num in mp:
            return mp[num], i
        mp[target - num] = i
    return None

n = int(input())
nums = [int(i) for i in input().split()]
target = int(input())

res = two_sum(nums, target)
if res == None:
    print("None")
else:
    for i in res:
        print(i, end=" ")

